import{_ as t,o as n,c as r,a2 as a}from"./chunks/framework.RycU2wFZ.js";const h=JSON.parse('{"title":"AgentFinOps × Agent Harness 架构结合与 MCP 借势运营方案","description":"","frontmatter":{},"headers":[],"relativePath":"plans/2026-11-09-agent-harness-and-mcp-integration-plan.md","filePath":"plans/2026-11-09-agent-harness-and-mcp-integration-plan.md"}'),s={name:"plans/2026-11-09-agent-harness-and-mcp-integration-plan.md"};function o(l,e,d,i,g,c){return n(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="agentfinops-×-agent-harness-架构结合与-mcp-借势运营方案" tabindex="-1">AgentFinOps × Agent Harness 架构结合与 MCP 借势运营方案 <a class="header-anchor" href="#agentfinops-×-agent-harness-架构结合与-mcp-借势运营方案" aria-label="Permalink to &quot;AgentFinOps × Agent Harness 架构结合与 MCP 借势运营方案&quot;">​</a></h1><blockquote><p><strong>版本</strong>：v1.0.0<br><strong>制定日期</strong>：2026-11-09<br><strong>核心定位</strong>：基于“30% 核心研发 + 70% 平台运营”双轮驱动战略（参见 <a href="./2026-11-08-agentpay-30-70-operations-and-code-plan">30/70 战略执行规划</a>），以 <strong>MCP（Model Context Protocol）与 OpenAI 兼容网关</strong> 为最大公约数，低成本适配 <a href="https://github.com/deepseek-ai/deepseek-harness" target="_blank" rel="noreferrer">DeepSeek Harness (<code>dsh</code>)</a>、<a href="https://www.workbuddy.cn/" target="_blank" rel="noreferrer">腾讯 WorkBuddy</a> 等行业热点 Agent Harness。<br><strong>关联规范</strong>：<a href="./../architecture/">企业级系统架构规范</a> | <a href="./../architecture/security-model">安全与威胁模型规范</a> | <a href="./../ecosystem/mcp-plugin">MCP 原生支付中间件规范</a></p></blockquote><hr><h2 id="_1-核心概念界定-什么是-agent-harness-为什么亟需-agentfinops" tabindex="-1">1. 核心概念界定：什么是 Agent Harness？为什么亟需 AgentFinOps？ <a class="header-anchor" href="#_1-核心概念界定-什么是-agent-harness-为什么亟需-agentfinops" aria-label="Permalink to &quot;1. 核心概念界定：什么是 Agent Harness？为什么亟需 AgentFinOps？&quot;">​</a></h2><h3 id="_1-1-agent-harness-的定义与核心解剖" tabindex="-1">1.1 Agent Harness 的定义与核心解剖 <a class="header-anchor" href="#_1-1-agent-harness-的定义与核心解剖" aria-label="Permalink to &quot;1.1 Agent Harness 的定义与核心解剖&quot;">​</a></h3><p>在 AI 工程领域，<strong>Agent Harness（智能体运行框架/控制套具）</strong> 是包裹在大语言模型（LLM）外层的确定性运行时基础设施，行业通行公式为 <strong><code>Agent = Model + Harness</code></strong>（<a href="https://martinfowler.com/articles/harness-engineering.html" target="_blank" rel="noreferrer">Martin Fowler: Harness Engineering</a>）。如果将 LLM 视为负责推理与输出意图的“大脑”，那么 Agent Harness 就是赋予其感知、记忆、工具执行与安全边界的“躯干与运行环境”（<a href="https://www.thoughtworks.com/insights/blog/machine-learning-and-ai/ai-agent-harness" target="_blank" rel="noreferrer">Thoughtworks: What is an AI agent harness?</a>）。</p><p>单纯的语言模型只是一个开环（Open-loop）的单次文本生成器，而 <a href="https://www.databricks.com/blog/ai-harness" target="_blank" rel="noreferrer">Agent Harness</a> 通过以下五大核心层将其转化为闭环（Closed-loop）的自主工作引擎（<a href="https://arize.com/blog/what-is-an-agent-harness/" target="_blank" rel="noreferrer">Arize AI</a>、<a href="https://learn.microsoft.com/en-us/agent-framework/concepts/harness" target="_blank" rel="noreferrer">Microsoft Learn</a>）：</p><ol><li><strong>执行控制循环（Control Loop）</strong>：驱动“推理（Reason）$\\to$ 行动（Act）$\\to$ 观察结果（Observe）$\\to$ 迭代修正”的多步闭环，直至达成目标或触发终止条件（<a href="https://www.thunai.ai/blog/ai-harness-vs-ai-agent" target="_blank" rel="noreferrer">Thunai AI</a>）。</li><li><strong>上下文与记忆编排（Context &amp; Memory）</strong>：动态组装系统指令、历史会话、外部文档与工具返回结果，并通过上下文压缩（Compaction）防止窗口溢出（<a href="https://www.nngroup.com/articles/agent-harness/" target="_blank" rel="noreferrer">NN/G: Agent Harness Definition</a>）。</li><li><strong>工具路由与沙箱执行（Tool Routing &amp; Sandbox）</strong>：拦截模型的工具调用提议，校验权限并在受控环境（容器、进程外守护进程）中执行真实操作（<a href="https://www.snowflake.com/en/artificial-intelligence/agents/harness/" target="_blank" rel="noreferrer">Snowflake: Agent Harness</a>）。</li><li><strong>安全护栏与人在回路（Guardrails &amp; HITL）</strong>：像控制论中的“调速器（Cybernetic Governor）”一样约束模型的不确定性输出，并在高风险操作前挂起任务等待人工审批（<a href="https://martinfowler.com/articles/harness-engineering.html" target="_blank" rel="noreferrer">Martin Fowler</a>）。</li><li><strong>全链路可观测性与评测（Observability &amp; Evals）</strong>：记录每一步的 Prompt、工具出入参、耗时与 Token 消耗，支撑回放审计与持续的 <a href="https://www.dawiso.com/glossary/agent-harness-engineering" target="_blank" rel="noreferrer">Harness Engineering</a> 迭代（<a href="https://www.langchain.com/blog/the-anatomy-of-an-agent-harness" target="_blank" rel="noreferrer">LangChain: The Anatomy of an Agent Harness</a>）。</li></ol><h3 id="_1-2-传统-agent-harness-的财务盲区与-agentfinops-的卡位" tabindex="-1">1.2 传统 Agent Harness 的财务盲区与 AgentFinOps 的卡位 <a class="header-anchor" href="#_1-2-传统-agent-harness-的财务盲区与-agentfinops-的卡位" aria-label="Permalink to &quot;1.2 传统 Agent Harness 的财务盲区与 AgentFinOps 的卡位&quot;">​</a></h3><p>研究表明，自主智能体高达 60% 以上的成本消耗在多轮循环重试与异常处理上，失控的循环任务甚至会比单轮对话多消耗上千倍的 Token 与外部 API 费用（<a href="https://www.thunai.ai/blog/ai-harness-vs-ai-agent" target="_blank" rel="noreferrer">Thunai AI</a>）。</p><p>传统 Agent Harness 聚焦于“如何让任务跑通”，但在企业生产环境中普遍缺失**“财务调速器（Financial Governor）”**：</p><ul><li><strong>缺乏硬性资金电闸</strong>：仅依赖固定步数上限（<code>max_iterations</code>），无法按实时消费金额或高频速率（RPM）秒级熔断。</li><li><strong>缺乏多级预算隔离与防悬挂记账</strong>：多个智能体共享上游商业模型或付费数据源的 Master Key，一旦单个 Harness 失控即可穿透整个部门预算，且网络超时极易引发资金悬挂（参见 <a href="./../architecture/security-model">安全与威胁模型规范 N1–N6</a>）。</li><li><strong>缺乏财务级语义反馈</strong>：普通网关仅返回 <code>500</code> 或超时错误，模型无法区分“接口临时故障（应当重试）”与“超出单笔预算上限（禁止重试，应当切换低成本方案）”。</li></ul><p><strong>AgentFinOps (AgentPay)</strong> 的核心定位正是嵌入或代理各类 Agent Harness 的<strong>企业级财务安全护栏层（Financial Guardrail Layer）</strong>。</p><hr><h2 id="_2-agentfinops-与-agent-harness-的五大通用结合切面" tabindex="-1">2. AgentFinOps 与 Agent Harness 的五大通用结合切面 <a class="header-anchor" href="#_2-agentfinops-与-agent-harness-的五大通用结合切面" aria-label="Permalink to &quot;2. AgentFinOps 与 Agent Harness 的五大通用结合切面&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                              Agent = Model + Agent Harness                             │</span></span>
<span class="line"><span>│                                                                                        │</span></span>
<span class="line"><span>│   ┌──────────────┐    1. 推理与工具提议    ┌───────────────────────────────────────┐   │</span></span>
<span class="line"><span>│   │  LLM 大模型  │ ──────────────────────&gt; │             Agent Harness             │   │</span></span>
<span class="line"><span>│   └──────────────┘                         │  • Control Loop  • Context &amp; Memory   │   │</span></span>
<span class="line"><span>│          ▲                                 │  • Tool Router   • Session Log        │   │</span></span>
<span class="line"><span>│          │ 5. 注入财务 Observation         └───────────────────┬───────────────────┘   │</span></span>
<span class="line"><span>└──────────┼─────────────────────────────────────────────────────┼───────────────────────┘</span></span>
<span class="line"><span>           │                                                     │ 2. OpenAI 路由 / MCP 调用</span></span>
<span class="line"><span>           │                                                     ▼</span></span>
<span class="line"><span>┌──────────┴─────────────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    AgentFinOps (企业级 AI 行为审计与资金防火墙网关)                    │</span></span>
<span class="line"><span>│                                                                                        │</span></span>
<span class="line"><span>│  [北向：模型计费代理 (/v1/chat/completions)]     [南向：MCP 协议计费网关 (SSE / Stdio)]│</span></span>
<span class="line"><span>│  • 四级树状配额锁 (租户-&gt;部门-&gt;项目-&gt;Agent)      • 三态防悬挂状态机 (Hold/Capture/Rel) │</span></span>
<span class="line"><span>│  • 滑动窗口 RPM 死循环秒级熔断                   • HTTP 402 异步挂起 + 飞书/企微审批   │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:left;">Agent Harness 核心层</th><th style="text-align:left;">结合方式与职责分工</th><th style="text-align:left;">对应 AgentFinOps 模块与机制</th><th style="text-align:left;">解决的核心生产风险</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1. 工具调用层（Tool Execution）</strong></td><td style="text-align:left;">用 <code>AgentPayClient</code> 替换 Harness 内部工具的原生请求，或将 MCP 工具流量统一指向网关</td><td style="text-align:left;"><code>agentpay-core-sdk</code> + <a href="./../../services/gateway">Go Gateway</a> + <a href="./../ecosystem/mcp-plugin">MCP 插件</a></td><td style="text-align:left;">收敛上游商业模型与付费 API 的 Master Key（AES-256-GCM 加密托管），防止宿主环境泄露密钥（N1 威胁）</td></tr><tr><td style="text-align:left;"><strong>2. 循环控制层（Loop Governor）</strong></td><td style="text-align:left;">在 Harness 每轮发起工具/模型调用前执行双层滑动窗口校验，超频或超额时物理切断循环</td><td style="text-align:left;">端侧 <code>SQLitePolicyEngine</code> + 网关级联配额校验器</td><td style="text-align:left;">毫秒级识别失控递归（<code>CIRCUIT_MAX_RPM_EXCEEDED</code>），3 秒内冻结钱包，防止死循环刷爆账单（N3 威胁）</td></tr><tr><td style="text-align:left;"><strong>3. 观察与反馈层（Observation Feedback）</strong></td><td style="text-align:left;">将网关拦截原因（402 挑战、单笔超限、熔断状态）封装为结构化 Observation 喂回模型上下文</td><td style="text-align:left;">金融防火墙错误码（如 <code>SINGLE_TX_CAP_EXCEEDED</code>）</td><td style="text-align:left;">让 LLM 感知“预算边界”，在被拒后主动放弃昂贵接口、切换低成本方案或向用户汇报，而非盲目重试</td></tr><tr><td style="text-align:left;"><strong>4. 审批挂起层（HITL Checkpoint）</strong></td><td style="text-align:left;">当模型请求高价值工具触发阈值时，Harness 捕获 <code>402</code> 响应并挂起当前执行协程，等待审批回调后自动重放</td><td style="text-align:left;"><a href="./2026-11-07-hitl-approval-architecture">402 异步挂起引擎</a> + 飞书/企微审批卡片 + Nonce 幂等重放</td><td style="text-align:left;">实现“小额毫秒级自动放行、中大额手机端一键审批、超额硬阻断”的三级风控梯次</td></tr><tr><td style="text-align:left;"><strong>5. 状态与可观测层（State &amp; Tracing）</strong></td><td style="text-align:left;">Harness 在请求头注入 <code>trace_id</code> 与组织上下文，网关执行原子记账并将真实成本回写至追踪看板</td><td style="text-align:left;">防悬挂三态状态机（<code>Hold/Capture/Release</code>）+ <a href="./../ecosystem/langfuse">Langfuse 协同</a></td><td style="text-align:left;">隔离模型“自报声明（Declared）”与网关“客观事实（Observed）”，杜绝超时悬挂扣款（N4 威胁）并实现部门级成本核算</td></tr></tbody></table><hr><h2 id="_3-典型标杆方案-deepseek-harness-与腾讯-workbuddy-架构对接" tabindex="-1">3. 典型标杆方案：DeepSeek Harness 与腾讯 WorkBuddy 架构对接 <a class="header-anchor" href="#_3-典型标杆方案-deepseek-harness-与腾讯-workbuddy-架构对接" aria-label="Permalink to &quot;3. 典型标杆方案：DeepSeek Harness 与腾讯 WorkBuddy 架构对接&quot;">​</a></h2><p><a href="https://github.com/deepseek-ai/deepseek-harness" target="_blank" rel="noreferrer">DeepSeek Harness (<code>dsh</code>)</a> 与 <a href="https://www.workbuddy.cn/" target="_blank" rel="noreferrer">腾讯 WorkBuddy</a> 分别代表了当前最受关注的两类 Agent Harness 架构范式：<strong>开源白盒插件化微内核</strong>与<strong>商业闭盒协议扩展工作台</strong>。</p><h3 id="_3-1-两类标杆-harness-的架构特征对比" tabindex="-1">3.1 两类标杆 Harness 的架构特征对比 <a class="header-anchor" href="#_3-1-两类标杆-harness-的架构特征对比" aria-label="Permalink to &quot;3.1 两类标杆 Harness 的架构特征对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">对比维度</th><th style="text-align:left;"><a href="https://www.deepseek.com/zh/harness/" target="_blank" rel="noreferrer">DeepSeek Harness (<code>dsh</code>)</a></th><th style="text-align:left;"><a href="https://www.workbuddy.cn/" target="_blank" rel="noreferrer">腾讯 WorkBuddy</a> / <a href="https://www.workbuddy.cn/docs/enterprise/" target="_blank" rel="noreferrer">Enterprise</a></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>核心架构范式</strong></td><td style="text-align:left;">基于 Cordis 框架的“万物皆插件（Everything is a Plugin）”微内核（<a href="https://www.eigent.ai/blog/deepseek-harness-agent-runtime" target="_blank" rel="noreferrer">Eigent AI</a>）</td><td style="text-align:left;">多 Agent 并行协作的全场景桌面客户端与企业托管平台（<a href="https://cloud.tencent.com/product/workbuddy" target="_blank" rel="noreferrer">腾讯云 WorkBuddy</a>）</td></tr><tr><td style="text-align:left;"><strong>控制循环可见性</strong></td><td style="text-align:left;"><strong>完全白盒</strong>：Agent Loop、Router、Tool Registry、Session Log 均为可热插拔组件（<a href="https://www.mindstudio.ai/blog/deepseek-harness-plugin-architecture" target="_blank" rel="noreferrer">MindStudio 架构解析</a>）</td><td style="text-align:left;"><strong>受控黑盒</strong>：主规划循环由平台托管，官方提示自定义模型持续触发调用时需用户自行关注第三方账户费用（<a href="https://www.workbuddy.cn/docs/workbuddy/From-Beginner-to-Expert-Guide/Function-Description/Model" target="_blank" rel="noreferrer">WorkBuddy 模型配置</a>）</td></tr><tr><td style="text-align:left;"><strong>核心扩展接口</strong></td><td style="text-align:left;">Cordis 插件生命周期钩子、前置代码门控（Gate）、任务授权票据（Mandate）及 OpenAI 兼容端点（<a href="https://www.mindstudio.ai/blog/deepseek-harness-plugin-architecture" target="_blank" rel="noreferrer">MindStudio</a>）</td><td style="text-align:left;"><a href="https://www.workbuddy.cn/docs/workbuddy/From-Beginner-to-Expert-Guide/Function-Description/Model" target="_blank" rel="noreferrer">自定义模型配置 (<code>models.json</code>)</a>、<a href="https://www.workbuddy.cn/docs/workbuddy/From-Beginner-to-Expert-Guide/Function-Description/MCP-Guide" target="_blank" rel="noreferrer">MCP 配置 (<code>mcp.json</code>)</a>、<a href="https://open.workbuddy.cn/docs/connector" target="_blank" rel="noreferrer">连接器 (Connector)</a> 与 <a href="https://www.workbuddy.cn/docs/workbuddy/From-Beginner-to-Expert-Guide/Function-Description/Skills-Market" target="_blank" rel="noreferrer">Skills 技能包</a></td></tr><tr><td style="text-align:left;"><strong>AgentFinOps 结合策略</strong></td><td style="text-align:left;"><strong>内核级插件注入（<code>dsh-plugin-finops</code>）+ MCP/模型双路网关</strong></td><td style="text-align:left;"><strong>协议边界代理（模型自定义协议代理 + MCP 网关）+ 财务感知 Skill</strong></td></tr></tbody></table><h3 id="_3-2-与-deepseek-harness-dsh-的四层结合设计" tabindex="-1">3.2 与 DeepSeek Harness (<code>dsh</code>) 的四层结合设计 <a class="header-anchor" href="#_3-2-与-deepseek-harness-dsh-的四层结合设计" aria-label="Permalink to &quot;3.2 与 DeepSeek Harness (\`dsh\`) 的四层结合设计&quot;">​</a></h3><p><a href="https://github.com/deepseek-ai/deepseek-harness" target="_blank" rel="noreferrer">DeepSeek Harness</a> 没有固定的特权核心，连驱动智能体的主循环（Loop）、工具注册表（Tool Registry）和权限模块都是通过 Cordis 进行时空组合（Spatiotemporal Composability）的插件（<a href="https://www.mindstudio.ai/blog/deepseek-harness-plugin-architecture" target="_blank" rel="noreferrer">MindStudio</a>）。AgentFinOps 可通过 <strong>“协议接入（零代码）+ 轻量 Cordis 插件（可选增强）”</strong> 结合：</p><ol><li><strong>前置门控与票据层（Gate &amp; Mandate 预算绑定）</strong>： <ul><li><strong>DSH 机制</strong>：在 DSH 的 Super Agent 架构中，外部触发事件进入模型推理前会先经过纯代码门控（Gate），并生成记录发起人、规则与执行边界的授权票据 <code>Mandate</code>（<a href="https://www.mindstudio.ai/blog/deepseek-harness-plugin-architecture" target="_blank" rel="noreferrer">MindStudio</a>）。</li><li><strong>结合方案</strong>：在 Gate 阶段对接 AgentFinOps 网关校验发起人所属部门/项目的可用余额，并将单次任务的预算硬顶（Task Budget Cap）和滑动窗口频率限制写入 <code>Mandate</code> 上下文（或透传 <code>X-AgentPay-Mandate-Cap</code> 请求头）。</li></ul></li><li><strong>主循环与多级路由层（Loop &amp; Router 动态降级）</strong>： <ul><li><strong>DSH 机制</strong>：DSH 将轻量级编排路由器（Router）与实际执行编码/分析的 Worker Agent 分离（<a href="https://www.mindstudio.ai/blog/deepseek-harness-plugin-architecture" target="_blank" rel="noreferrer">MindStudio</a>）。</li><li><strong>结合方案</strong>：当任务消耗接近预算阈值的 80% 时，根据网关返回的剩余配额信号动态调整 Router 的模型路由策略，将后续边缘推理从旗舰模型平滑降级至轻量模型；一旦触发死循环阈值，利用 Cordis 的时间可组合性（Temporal Composability）干净卸载当前 Worker。</li></ul></li><li><strong>工具注册表与沙箱拦截层（Tool Registry &amp; MCP 402 HITL）</strong>： <ul><li><strong>DSH 机制</strong>：支持接入外部工具、MCP 服务与本地沙箱（<a href="https://open-design.ai/agents/deepseek-harness-design/" target="_blank" rel="noreferrer">OpenDesign</a>）。</li><li><strong>结合方案</strong>：将 DSH 的外部付费工具统一挂载到 AgentFinOps 的 MCP 网关下。当 Worker 调用高价值 API 触发 <code>HTTP 402 Payment Required</code> 时，挂起当前 Session 并通过飞书/企微推送审批卡片，批准后携带幂等凭证恢复执行。</li></ul></li><li><strong>会话日志与三态账本对账层（Session Log &amp; Ledger Sync）</strong>： <ul><li><strong>结合方案</strong>：将 DSH 的 Session Log <code>trace_id</code> 与网关端通过 <code>Hold -&gt; Capture -&gt; Release</code> 三态状态机确认的客观扣费流水双向绑定，实现按插件/子智能体（Subagent）维度的精准成本核算。</li></ul></li></ol><h3 id="_3-3-与腾讯-workbuddy-的三切面零侵入结合设计" tabindex="-1">3.3 与腾讯 WorkBuddy 的三切面零侵入结合设计 <a class="header-anchor" href="#_3-3-与腾讯-workbuddy-的三切面零侵入结合设计" aria-label="Permalink to &quot;3.3 与腾讯 WorkBuddy 的三切面零侵入结合设计&quot;">​</a></h3><p><a href="https://www.workbuddy.cn/docs/workbuddy/Overview" target="_blank" rel="noreferrer">腾讯 WorkBuddy</a> 支持一句话拆解复杂任务并由多 Agent 并行推进（<a href="https://cloud.tencent.com/product/workbuddy" target="_blank" rel="noreferrer">腾讯云 WorkBuddy</a>）。由于其内部主循环闭源且多 Agent 并行会成倍放大调用频次，AgentFinOps 可直接利用其官方开放的<strong>三大标准配置切面</strong>实现零代码修改的外部治理闭环：</p><ol><li><strong>模型底座切面：通过“自定义模型 + 自定义协议”接入 Go 网关</strong>： <ul><li><strong>WorkBuddy 机制</strong>：允许在本地 <code>workbuddy/models.json</code> 或图形界面中配置第三方大模型，并提供**“自定义协议”开关**——开启后针对经过网关或代理层封装的非标准 URL 直接发起请求，跳过路径校验（<a href="https://www.workbuddy.cn/docs/workbuddy/From-Beginner-to-Expert-Guide/Function-Description/Model" target="_blank" rel="noreferrer">WorkBuddy 模型配置文档</a>）。</li><li><strong>结合方案</strong>：企业员工不在本地保存上游大模型的真实 Master Key，而是统一在 WorkBuddy 中填入 AgentFinOps Go 网关地址及受控的员工级/项目级 <code>apk_live_xxx</code> 密钥。多 Agent 并行产生的所有 LLM 推理流量全部流经网关，由网关流式解析 SSE 响应计算真实 Token 成本，并通过四级树状配额实时拦截超支请求。</li></ul></li><li><strong>工具调用切面：通过 <code>mcp.json</code> / 连接器挂载 AgentFinOps MCP 网关</strong>： <ul><li><strong>WorkBuddy 机制</strong>：通过 <code>~/.workbuddy/mcp.json</code>（支持 SSE 与本地模式）及开放平台 <a href="https://open.workbuddy.cn/docs/connector" target="_blank" rel="noreferrer">连接器（Connector）</a> 扩展外部业务系统、数据库与企微机器人能力（<a href="https://www.workbuddy.cn/docs/workbuddy/From-Beginner-to-Expert-Guide/Function-Description/MCP-Guide" target="_blank" rel="noreferrer">WorkBuddy MCP 指南</a>）。</li><li><strong>结合方案</strong>：在 AgentFinOps 网关上暴露标准 <strong>MCP SSE 代理端点</strong>。WorkBuddy 发起的每一次付费 MCP Tool Call 均先经过网关的 <code>Hold -&gt; Capture -&gt; Release</code> 三态预占与滑动窗口限流；若上游超时，网关自动 Release 预留资金，保障多 Agent 并行调用时账本零误差。</li></ul></li><li><strong>认知与审批切面：发布配套的“财务感知 Skill”与企微闭环</strong>： <ul><li><strong>WorkBuddy 机制</strong>：<a href="https://open.workbuddy.cn/docs/connector" target="_blank" rel="noreferrer">连接器规范</a> 与 <a href="https://www.workbuddy.cn/docs/workbuddy/From-Beginner-to-Expert-Guide/Function-Description/Skills-Market" target="_blank" rel="noreferrer">Skills 系统</a> 使用 <code>skills/</code> 目录下的 <code>Markdown + YAML Frontmatter</code> 文档指导 AI 理解何时以及如何使用工具（<a href="https://www.workbuddy.cn/docs/workbuddy/From-Beginner-to-Expert-Guide/Practice-Cases/Practice-Eight" target="_blank" rel="noreferrer">自定义技能实践</a>）。</li><li><strong>结合方案</strong>：随附一份 <code>AgentFinOps-Governance Skill</code>： <ul><li><strong>异常语义引导</strong>：在 Skill 规则中明确声明当收到 <code>SINGLE_TX_CAP_EXCEEDED</code>（单笔超限）或 <code>CIRCUIT_BREAKER_OPEN</code>（频率超限）时，禁止原地重试，必须停止当前子任务或改用低成本替代工具。</li><li><strong>企微原生审批联动</strong>：WorkBuddy 原生深度集成企业微信生态（<a href="https://www.workbuddy.cn/docs/workbuddy/From-Beginner-to-Expert-Guide/Function-Description/MCP-Guide" target="_blank" rel="noreferrer">WorkBuddy MCP 指南</a>），当大额调用触发网关 <code>402</code> 挂起时，AgentFinOps 直接向负责人企业微信推送审批卡片，批准后由 Skill 引导 WorkBuddy 完成幂等重放。</li></ul></li></ul></li></ol><hr><h2 id="_4-面向-蹭热点运营-的最小化研发与内容矩阵规划" tabindex="-1">4. 面向“蹭热点运营”的最小化研发与内容矩阵规划 <a class="header-anchor" href="#_4-面向-蹭热点运营-的最小化研发与内容矩阵规划" aria-label="Permalink to &quot;4. 面向“蹭热点运营”的最小化研发与内容矩阵规划&quot;">​</a></h2><p>为了契合“30% 核心研发 + 70% 平台运营”策略，研发侧不必为每个外部工具单独开发重度插件，而是用**“1 套网关通用协议层 + N 份热点工具配置模板”**撬动最大的社区声量。</p><h3 id="_4-1-研发侧最小化支撑清单-围绕-mcp-路线图" tabindex="-1">4.1 研发侧最小化支撑清单（围绕 MCP 路线图） <a class="header-anchor" href="#_4-1-研发侧最小化支撑清单-围绕-mcp-路线图" aria-label="Permalink to &quot;4.1 研发侧最小化支撑清单（围绕 MCP 路线图）&quot;">​</a></h3><ol><li><strong>Go 网关 MCP 透明代理路由（MCP SSE Proxy）</strong>： <ul><li>在现有 <a href="./../ecosystem/mcp-plugin">MCP 插件规范</a> 基础上，支持在 <code>gateway.yaml</code> 中直接为上游 MCP Server 配置工具级价格（<code>price_base_units</code>），使任何仅支持 <code>mcp.json</code> 配置的闭盒客户端（如 WorkBuddy、Cursor、Claude Desktop）无需编写 SDK 代码即可接入。</li></ul></li><li><strong>结构化财务拦截提示（LLM-Friendly Denial Formatter）</strong>： <ul><li>当网关触发限额或 <code>402</code> 挂起时，除了返回 HTTP 状态码外，在 MCP Tool Result 或 OpenAI 兼容响应中自动附带结构化的中文/英文引导提示（告知模型当前剩余配额、被拒原因及建议动作），确保任何 Harness 的主循环都能平滑理解。</li></ul></li><li><strong>热点工具一键配置模板库（<code>examples/harnesses/</code>）</strong>： <ul><li>预置 <code>deepseek-harness/</code> 与 <code>tencent-workbuddy/</code> 两个示例目录，仅包含现成的 <code>mcp.json</code>、<code>models.json</code>、<code>gateway.yaml</code> 和 <code>SKILL.md</code> 模板，方便读者 3 分钟复制体验。</li></ul></li></ol><h3 id="_4-2-运营侧借势热点选题矩阵-公众号-掘金-知乎-b站" tabindex="-1">4.2 运营侧借势热点选题矩阵（公众号 / 掘金 / 知乎 / B站） <a class="header-anchor" href="#_4-2-运营侧借势热点选题矩阵-公众号-掘金-知乎-b站" aria-label="Permalink to &quot;4.2 运营侧借势热点选题矩阵（公众号 / 掘金 / 知乎 / B站）&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">阶段</th><th style="text-align:left;">借势热点关键词</th><th style="text-align:left;">拟定爆款标题</th><th style="text-align:left;">核心痛点钩子与视觉演示物料</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>第一波：概念卡位</strong></td><td style="text-align:left;"><code>Harness Engineering</code><br><code>Loop Engineering</code><br><code>Agent 账单失控</code></td><td style="text-align:left;">《从 Prompt Engineering 到 Harness Engineering：为什么你的 Agent 缺一个“财务调速器”？》</td><td style="text-align:left;">引用 <a href="https://martinfowler.com/articles/harness-engineering.html" target="_blank" rel="noreferrer">Martin Fowler 控制论调速器观点</a> 与 <a href="https://www.thunai.ai/blog/ai-harness-vs-ai-agent" target="_blank" rel="noreferrer">60% 循环重试成本数据</a>，展示“裸奔 Harness Loop”与“挂载 AgentFinOps 的企业级 Harness”架构对比图</td></tr><tr><td style="text-align:left;"><strong>第二波：办公热点</strong></td><td style="text-align:left;"><code>腾讯 WorkBuddy</code><br><code>多 Agent 并行</code><br><code>MCP 配置实战</code><br><code>企业微信审批</code></td><td style="text-align:left;">《当团队用上腾讯 WorkBuddy 多 Agent 并行，企业如何用 MCP 网关管住 API 账单与密钥安全？》</td><td style="text-align:left;">紧扣 <a href="https://www.workbuddy.cn/docs/workbuddy/From-Beginner-to-Expert-Guide/Function-Description/Model" target="_blank" rel="noreferrer">WorkBuddy 官方模型与技能文档中的费用提醒</a>，演示通过 <code>mcp.json</code> 挂载 AgentFinOps 后，多 Agent 并发调用触发企微 <code>402</code> 手机卡片审批的动图</td></tr><tr><td style="text-align:left;"><strong>第三波：极客热点</strong></td><td style="text-align:left;"><code>DeepSeek Harness</code><br><code>万物皆插件 (Cordis)</code><br><code>Coding Agent 安全</code></td><td style="text-align:left;">《拆解 DeepSeek Harness 万物皆插件架构：如何基于 MCP 与三态账本构建零信任企业 Agent？》</td><td style="text-align:left;">剖析 <a href="https://github.com/deepseek-ai/deepseek-harness" target="_blank" rel="noreferrer">DeepSeek Harness (<code>dsh</code>)</a> 的 <code>Gate/Mandate</code> 机制（<a href="https://www.mindstudio.ai/blog/deepseek-harness-plugin-architecture" target="_blank" rel="noreferrer">MindStudio</a>），演示如何用 <code>Hold/Capture/Release</code> 三态状态机与四级预算锁补齐开源 Coding Agent 的政企合规拼图</td></tr></tbody></table>`,35)])])}const u=t(s,[["render",o]]);export{h as __pageData,u as default};
